import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mul, add, mix, texture, uniform, time, positionLocal, normalLocal } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  // STAGE: Create backdrop plane with gradient (7x6 units at z=-2.5)
  const backdropGeo = new THREE.PlaneGeometry(7, 6);
  const backdropMat = new THREE.MeshBasicMaterial({
    color: 0x0b0b10, // surface (near-black)
    side: THREE.DoubleSide
  });
  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -2.5;
  group.add(backdrop);

  // PRIMARY OBJECT: Tessellated displacement plane
  const planeGeo = new THREE.PlaneGeometry(3.5, 2.2, 64, 64);

  // Load textures for displacement and color
  let displacementTex = null;
  let colorTex = null;
  let resourceCleanup = [];

  // Load depth map for displacement
  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      displacementTex = tex;
      if (planeMat.material) {
        planeMat.material.fragmentNode = buildFragmentNode();
      }
    });
  }

  // Load color texture
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      colorTex = tex;
      if (planeMat.material) {
        planeMat.material.fragmentNode = buildFragmentNode();
        planeMat.material.needsUpdate = true;
      }
    });
  }

  // Build fragment node with TSL
  function buildFragmentNode() {
    if (!colorTex) return undefined;
    const baseColor = texture(colorTex, uv());
    const finalColor = mix(baseColor, vec3(0.93, 0.93, 0.95), 0.05); // slight paper tint
    return finalColor;
  }

  // Build displacement node with TSL
  function buildDisplacementNode() {
    if (!displacementTex) return null;
    const dispMap = texture(displacementTex, uv());
    const dispAmount = mul(dispMap.r, 0.15); // subtle displacement depth
    return mul(normalLocal, dispAmount);
  }

  // TSL Material with displacement
  const planeMat = new MeshStandardNodeMaterial({
    color: 0xe8ecf2, // paper fallback
    metalness: 0.35,
    roughness: 0.6,
    clearcoat: 0.15,
    emissive: 0x0b0b10,
    emissiveIntensity: 0.1,
    side: THREE.DoubleSide
  });

  // Set up displacement on vertex shader
  const dispNode = buildDisplacementNode();
  if (dispNode) {
    planeMat.positionNode = add(positionLocal, dispNode);
  }

  const plane = new THREE.Mesh(planeGeo, planeMat);
  plane.position.copy(new THREE.Vector3(1.25, -0.2, 0));
  plane.castShadow = true;
  plane.receiveShadow = true;
  group.add(plane);

  // RIM LIGHT (accent-hued, opposite key)
  const rimLight = new THREE.DirectionalLight(0xff2a38, 0.65);
  rimLight.position.set(-2, 1.5, 1.5);
  rimLight.castShadow = false;
  group.add(rimLight);

  // KEY LIGHT (warm, moderate)
  const keyLight = new THREE.DirectionalLight(0xffffff, 1.0);
  keyLight.position.set(2, 1.2, 1);
  keyLight.castShadow = false;
  group.add(keyLight);

  // CONTACT SHADOW under the plane
  const shadowGeo = new THREE.PlaneGeometry(4.2, 2.8);
  const shadowMat = new THREE.MeshBasicMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.35,
    side: THREE.DoubleSide
  });
  const shadow = new THREE.Mesh(shadowGeo, shadowMat);
  shadow.position.set(1.25, -0.2, -0.05);
  shadow.receiveShadow = false;
  group.add(shadow);

  // ENTRANCE ANIMATION (weighted-settle)
  plane.scale.set(0.95, 0.95, 1);
  plane.position.y -= 0.3;
  const enterTimeline = gsap.timeline();
  enterTimeline.to(
    plane.position,
    { y: -0.2, duration: 0.7, ease: 'power3.out' },
    0
  );
  enterTimeline.to(
    plane.scale,
    { x: 1, y: 1, duration: 0.9, ease: 'back.out', overshoot: 1.04 },
    0
  );
  resourceCleanup.push(() => enterTimeline.kill());

  // HOVER INTERACTION: rise-in + depth-rotate
  const hoverState = { isHovering: false };
  const hoverTimeline = gsap.timeline({ paused: true });

  function setupHoverListeners() {
    // Apply depth-rotate primitive on hover
    const depthRotateResult = ctx.primitives['depth-rotate'](plane, { maxDeg: 8 });
    resourceCleanup.push(() => depthRotateResult.cleanup?.());

    // Rise-in animation (y +0.15 on hover)
    hoverTimeline.to(
      plane.position,
      { y: -0.05, duration: 0.4, ease: 'power2.out' },
      0
    );

    plane.userData.handlers = plane.userData.handlers || {};
    plane.userData.handlers.mouseenter = () => {
      hoverState.isHovering = true;
      hoverTimeline.play();
    };
    plane.userData.handlers.mouseleave = () => {
      hoverState.isHovering = false;
      hoverTimeline.reverse();
    };
    plane.userData.handlers.click = () => {
      ctx.emit('navigate', { to: 'hub-pricing.select' });
    };
  }

  setupHoverListeners();

  // PARALLAX-SCROLL PRIMITIVE
  const scrollResult = ctx.primitives['parallax-scroll'](plane, { intensity: 0.4, trigger: 'scroll' });
  resourceCleanup.push(() => scrollResult.cleanup?.());

  // TEXT CONTENT (if present; pricing row would have title + meta in parent or sibling, not here)
  // This node is the visual plane itself; text is handled by siblings (hub-pricing-card-0-label, etc.)

  // CLEANUP
  group.userData.cleanup = () => {
    resourceCleanup.forEach(fn => fn());
    planeMat.dispose?.();
    backdropMat.dispose?.();
    shadowMat.dispose?.();
    planeGeo.dispose?.();
    backdropGeo.dispose?.();
    shadowGeo.dispose?.();
    if (displacementTex) displacementTex.dispose?.();
    if (colorTex) colorTex.dispose?.();
    enterTimeline.kill();
    hoverTimeline.kill();
  };

  return group;
}
